"""Best-effort in-memory code cache generated by the Wasm preinit interpreter."""

from __future__ import annotations

import hashlib
import json
import marshal
import struct
import sys
import sysconfig
import types

FORMAT = "tobkiri.schema-preinit-code-cache/1"
MAX_CACHE_ACCOUNTED_BYTES = 8 * 1024 * 1024
MAX_TEMPORARY_BYTES = 16 * 1024 * 1024
MAX_METADATA_BYTES = 1024 * 1024
MAX_METADATA_RECORD_BYTES = MAX_METADATA_BYTES - 4096
MAX_ENTRIES = 512
MAX_SOURCE_BYTES_PER_ENTRY = 1024 * 1024
MAX_PRIME_ATTEMPTS = 512
MAX_PRIME_SOURCE_BYTES = 8 * 1024 * 1024
MAX_PREINIT_SEEN = 512
CAPTURE_LIMIT_BYTES = 64 * 1024 * 1024
STORE_LIMIT_BYTES = 128 * 1024 * 1024

_CONFIGURED = False
_OPEN = False
_SEALED = False
_INTERPRETER = None
_CACHE = {}
_CACHE_GRAPH_BYTES = 0
_RECORD_BYTES = 0
_REPORT_TEXT = None
_PREINIT_COMPILE_CALLS = 0
_PREINIT_CACHED_CALLS = 0
_PREINIT_SEEN: set[tuple] | None = set()
_PREINIT_PRIME_STARTED = False
_PREINIT_PRIME_CALLS = 0
_PREINIT_PRIME_COMPLETED = 0
_PREINIT_PRIME_SOURCE_BYTES = 0
_PREINIT_PRIME_SKIPPED = {
    "seen_before_prime": 0,
    "not_importable": 0,
    "shadowed_path": 0,
    "source_limit": 0,
    "entry_limit": 0,
    "attempt_limit": 0,
    "compile_error_fallback": 0,
}
_UNCACHED = {
    "entry_limit": 0,
    "metadata_limit": 0,
    "memory_limit": 0,
    "marshal_error": 0,
}
_RUNTIME_HITS = 0
_RUNTIME_MISSES = 0
_RUNTIME_COMPILES = 0
_MARSHAL_LOADS = 0
_SOURCE_TREE_ACCOUNTED_BYTES = 0
_PEAK_TEMPORARY_BYTES = 0
_PEAK_CODE_GRAPH_BYTES = 0
_PEAK_MARSHAL_BYTES = 0
_PEAK_COMBINED_STORE_BYTES = 0


def _interpreter_record() -> dict:
    implementation = sys.implementation
    return {
        "implementation": implementation.name,
        "python_version": list(sys.version_info[:3]),
        "version_string": sys.version[:256],
        "hexversion": sys.hexversion,
        "cache_tag": implementation.cache_tag,
        "soabi": sysconfig.get_config_var("SOABI"),
        "pointer_bits": struct.calcsize("P") * 8,
        "optimize": sys.flags.optimize,
        "marshal_version": marshal.version,
    }


def configure() -> None:
    """Open preinit collection only in the fixed 32-bit Wasm CPython runtime."""
    global _CONFIGURED, _OPEN, _INTERPRETER
    if _CONFIGURED or _SEALED:
        raise RuntimeError("preinit code cache was already configured")
    identity = _interpreter_record()
    if (
        identity["implementation"] != "cpython"
        or identity["python_version"] != [3, 13, 16]
        or identity["pointer_bits"] != 32
        or not isinstance(identity["soabi"], str)
        or "wasm32" not in identity["soabi"]
        or type(identity["optimize"]) is not int
        or type(identity["marshal_version"]) is not int
    ):
        raise RuntimeError("code cache requires the fixed Wasm CPython preinit")
    _INTERPRETER = identity
    _CONFIGURED = True
    _OPEN = True


def _code_graph_size(root: types.CodeType) -> int:
    """Conservatively measure a code object and its immutable constant graph."""
    pending = [root]
    seen = set()
    total = 0
    while pending:
        value = pending.pop()
        identity = id(value)
        if identity in seen:
            continue
        seen.add(identity)
        value_type = type(value)
        if value_type is types.CodeType:
            total += sys.getsizeof(value)
            pending.extend(
                (
                    value.co_consts,
                    value.co_names,
                    value.co_varnames,
                    value.co_freevars,
                    value.co_cellvars,
                    value.co_filename,
                    value.co_name,
                    value.co_qualname,
                    value.co_linetable,
                    value.co_exceptiontable,
                )
            )
        elif value_type in (tuple, frozenset):
            total += sys.getsizeof(value)
            pending.extend(value)
        elif value_type in (
            str,
            bytes,
            int,
            float,
            complex,
            bool,
            type(None),
            type(Ellipsis),
        ):
            total += sys.getsizeof(value)
        else:
            raise TypeError("unexpected object in compiled code constant graph")
    return total


def _owned_size(value: object, seen: set[int] | None = None) -> int:
    """Estimate retained bytes for exact built-in cache containers and values."""
    if seen is None:
        seen = set()
    identity = id(value)
    if identity in seen:
        return 0
    seen.add(identity)
    value_type = type(value)
    total = sys.getsizeof(value)
    if value_type is dict:
        for key, item in value.items():
            total += _owned_size(key, seen) + _owned_size(item, seen)
    elif value_type in (tuple, list, set, frozenset):
        for item in value:
            total += _owned_size(item, seen)
    return total


def _cache_accounted_bytes(report_text: str | None = None) -> int:
    selected_report = _REPORT_TEXT if report_text is None else report_text
    report_bytes = 0 if selected_report is None else sys.getsizeof(selected_report)
    seen_bytes = 0 if _PREINIT_SEEN is None else _owned_size(_PREINIT_SEEN)
    return (
        _owned_size(_CACHE)
        + seen_bytes
        + _CACHE_GRAPH_BYTES
        + sys.getsizeof(_RECORD_BYTES)
        + report_bytes
    )


def _source_identity(
    fullname: str, source_name: str, source: bytes, filename: str
) -> tuple[tuple, str]:
    if (
        type(fullname) is not str
        or type(source_name) is not str
        or type(source) is not bytes
        or type(filename) is not str
    ):
        raise TypeError("captured loader identity must use exact strings and bytes")
    digest = hashlib.sha256(source).hexdigest()
    identity = (
        fullname,
        source_name,
        filename,
        digest,
        json.dumps(_INTERPRETER, sort_keys=True, separators=(",", ":")),
    )
    return identity, digest


def _record_preinit_code(
    identity: tuple,
    fullname: str,
    source_name: str,
    source: bytes,
    filename: str,
    digest: str,
    code: types.CodeType,
) -> None:
    global _CACHE_GRAPH_BYTES, _RECORD_BYTES, _PREINIT_CACHED_CALLS
    global _PEAK_TEMPORARY_BYTES, _PEAK_CODE_GRAPH_BYTES, _PEAK_MARSHAL_BYTES
    global _PEAK_COMBINED_STORE_BYTES
    if identity in _CACHE:
        _PREINIT_CACHED_CALLS += 1
        return
    if len(_CACHE) >= MAX_ENTRIES:
        _UNCACHED["entry_limit"] += 1
        return
    if len(source) > MAX_SOURCE_BYTES_PER_ENTRY:
        _UNCACHED["memory_limit"] += 1
        return
    graph_bytes = _code_graph_size(code)
    existing = _cache_accounted_bytes()
    source_tree_bytes = _SOURCE_TREE_ACCOUNTED_BYTES
    conservative_temporary = existing + (graph_bytes * 16) + (len(source) * 8) + 65536
    if (
        existing + graph_bytes > MAX_CACHE_ACCOUNTED_BYTES
        or source_tree_bytes + existing + graph_bytes > CAPTURE_LIMIT_BYTES
        or conservative_temporary > MAX_TEMPORARY_BYTES
        or graph_bytes > MAX_TEMPORARY_BYTES
        or source_tree_bytes + conservative_temporary > STORE_LIMIT_BYTES
    ):
        _UNCACHED["memory_limit"] += 1
        return
    _PEAK_TEMPORARY_BYTES = max(_PEAK_TEMPORARY_BYTES, conservative_temporary)
    _PEAK_COMBINED_STORE_BYTES = max(
        _PEAK_COMBINED_STORE_BYTES, source_tree_bytes + conservative_temporary
    )
    try:
        payload = marshal.dumps(code)
    except Exception:
        _UNCACHED["marshal_error"] += 1
        return
    marshal_temporary = existing + graph_bytes + len(payload)
    _PEAK_TEMPORARY_BYTES = max(_PEAK_TEMPORARY_BYTES, marshal_temporary)
    _PEAK_MARSHAL_BYTES = max(_PEAK_MARSHAL_BYTES, len(payload))
    _PEAK_COMBINED_STORE_BYTES = max(
        _PEAK_COMBINED_STORE_BYTES, source_tree_bytes + marshal_temporary
    )
    if (
        len(payload) > MAX_CACHE_ACCOUNTED_BYTES
        or marshal_temporary > MAX_TEMPORARY_BYTES
        or source_tree_bytes + marshal_temporary > STORE_LIMIT_BYTES
    ):
        _UNCACHED["memory_limit"] += 1
        return
    record = {
        "fullname": fullname,
        "source_name": source_name,
        "source_bytes": len(source),
        "source_sha256": digest,
        "filename": filename,
        "compile_mode": "exec",
        "compile_flags": 0,
        "dont_inherit": True,
        "optimize_argument": -1,
        "actual_optimize": _INTERPRETER["optimize"],
        "marshal_version": _INTERPRETER["marshal_version"],
        "code_graph_bytes": graph_bytes,
        "cache_bytes": len(payload),
        "cache_sha256": hashlib.sha256(payload).hexdigest(),
    }
    record_size = len(
        json.dumps(record, ensure_ascii=True, sort_keys=True, separators=(",", ":"))
    )
    if _RECORD_BYTES + record_size > MAX_METADATA_RECORD_BYTES:
        _UNCACHED["metadata_limit"] += 1
        return
    _CACHE[identity] = {"record": record, "payload": payload}
    _CACHE_GRAPH_BYTES += graph_bytes
    _RECORD_BYTES += record_size
    accounted = _cache_accounted_bytes()
    temporary = existing + graph_bytes + len(payload) + record_size
    _PEAK_TEMPORARY_BYTES = max(_PEAK_TEMPORARY_BYTES, temporary)
    _PEAK_COMBINED_STORE_BYTES = max(
        _PEAK_COMBINED_STORE_BYTES, source_tree_bytes + temporary
    )
    _PEAK_CODE_GRAPH_BYTES = max(_PEAK_CODE_GRAPH_BYTES, graph_bytes)
    _PEAK_MARSHAL_BYTES = max(_PEAK_MARSHAL_BYTES, len(payload))
    if (
        accounted > MAX_CACHE_ACCOUNTED_BYTES
        or source_tree_bytes + accounted > CAPTURE_LIMIT_BYTES
        or temporary > MAX_TEMPORARY_BYTES
        or source_tree_bytes + temporary > STORE_LIMIT_BYTES
    ):
        _CACHE.pop(identity)
        _CACHE_GRAPH_BYTES -= graph_bytes
        _RECORD_BYTES -= record_size
        _UNCACHED["memory_limit"] += 1
        return
    _PREINIT_CACHED_CALLS += 1


def get_code(
    fullname: str,
    source_name: str,
    source: bytes,
    filename: str,
    source_tree_accounted_bytes: int,
) -> types.CodeType:
    """Compile unchanged source in preinit; later load fresh cache objects."""
    global _PREINIT_COMPILE_CALLS, _RUNTIME_HITS, _RUNTIME_MISSES
    global _RUNTIME_COMPILES, _MARSHAL_LOADS, _SOURCE_TREE_ACCOUNTED_BYTES
    global _PEAK_COMBINED_STORE_BYTES
    if (
        type(source_tree_accounted_bytes) is not int
        or not 0 <= source_tree_accounted_bytes <= CAPTURE_LIMIT_BYTES
    ):
        raise ValueError("captured source-tree accounting is outside its bound")
    _SOURCE_TREE_ACCOUNTED_BYTES = max(
        _SOURCE_TREE_ACCOUNTED_BYTES, source_tree_accounted_bytes
    )
    _PEAK_COMBINED_STORE_BYTES = max(
        _PEAK_COMBINED_STORE_BYTES, _SOURCE_TREE_ACCOUNTED_BYTES
    )
    identity, digest = _source_identity(fullname, source_name, source, filename)
    if _SEALED:
        cached = _CACHE.get(identity)
        if cached is None:
            _RUNTIME_MISSES += 1
            _RUNTIME_COMPILES += 1
            return compile(source, filename, "exec", dont_inherit=True)
        record = cached["record"]
        payload = cached["payload"]
        if (
            record["source_sha256"] != digest
            or record["filename"] != filename
            or record["actual_optimize"] != sys.flags.optimize
            or record["marshal_version"] != marshal.version
            or source_tree_accounted_bytes > CAPTURE_LIMIT_BYTES
            or hashlib.sha256(payload).hexdigest() != record["cache_sha256"]
        ):
            _RUNTIME_MISSES += 1
            _RUNTIME_COMPILES += 1
            return compile(source, filename, "exec", dont_inherit=True)
        runtime_temporary = (
            _cache_accounted_bytes() + record["code_graph_bytes"] + len(payload) + 65536
        )
        if (
            _SOURCE_TREE_ACCOUNTED_BYTES + _cache_accounted_bytes()
            > CAPTURE_LIMIT_BYTES
            or runtime_temporary > MAX_TEMPORARY_BYTES
            or _SOURCE_TREE_ACCOUNTED_BYTES + runtime_temporary > STORE_LIMIT_BYTES
        ):
            _RUNTIME_MISSES += 1
            _RUNTIME_COMPILES += 1
            return compile(source, filename, "exec", dont_inherit=True)
        try:
            code = marshal.loads(payload)
        except Exception:
            _RUNTIME_MISSES += 1
            _RUNTIME_COMPILES += 1
            return compile(source, filename, "exec", dont_inherit=True)
        if type(code) is not types.CodeType or code.co_filename != filename:
            _RUNTIME_MISSES += 1
            _RUNTIME_COMPILES += 1
            return compile(source, filename, "exec", dont_inherit=True)
        _RUNTIME_HITS += 1
        _MARSHAL_LOADS += 1
        return code

    _PREINIT_COMPILE_CALLS += 1
    if _PREINIT_SEEN is not None and len(_PREINIT_SEEN) < MAX_PREINIT_SEEN:
        _PREINIT_SEEN.add(identity)
    code = compile(source, filename, "exec", dont_inherit=True)
    if _OPEN and _CONFIGURED and type(code) is types.CodeType:
        try:
            _record_preinit_code(
                identity, fullname, source_name, source, filename, digest, code
            )
        except Exception:
            _UNCACHED["memory_limit"] += 1
    return code


def prime_sources(finder: object) -> None:
    """Compile only resolvable captured modules; never execute module bodies."""
    global _PREINIT_PRIME_STARTED, _PREINIT_PRIME_CALLS
    global _PREINIT_PRIME_COMPLETED, _PREINIT_PRIME_SOURCE_BYTES
    if not _CONFIGURED or not _OPEN or _SEALED or _PREINIT_PRIME_STARTED:
        raise RuntimeError("preinit source priming is not open")
    _PREINIT_PRIME_STARTED = True
    tree = finder.tree
    files = tree.files
    if len(files) > 4096 or type(finder.root) is not str:
        raise ValueError("captured module inventory exceeds the existing bound")
    for source_name in sorted(files):
        if type(source_name) is not str or not source_name.endswith(".py"):
            continue
        if source_name.endswith("/__init__.py"):
            module_path = source_name[: -len("/__init__.py")]
        else:
            module_path = source_name[:-3]
        fullname = module_path.replace("/", ".")
        if (
            not fullname
            or fullname.replace(".", "/") != module_path
            or "\x00" in fullname
            or len(fullname) > 4096
        ):
            _PREINIT_PRIME_SKIPPED["not_importable"] += 1
            continue
        try:
            spec = finder.find_spec(fullname)
        except Exception:
            _PREINIT_PRIME_SKIPPED["not_importable"] += 1
            continue
        if spec is None or spec.loader is None:
            _PREINIT_PRIME_SKIPPED["not_importable"] += 1
            continue
        loader = spec.loader
        if loader.name != fullname or loader.source != source_name:
            _PREINIT_PRIME_SKIPPED["shadowed_path"] += 1
            continue
        source = files[source_name]
        filename = finder.root + "/" + source_name
        identity, _ = _source_identity(fullname, source_name, source, filename)
        if _PREINIT_SEEN is not None and identity in _PREINIT_SEEN:
            _PREINIT_PRIME_SKIPPED["seen_before_prime"] += 1
            continue
        if len(source) > MAX_SOURCE_BYTES_PER_ENTRY or (
            _PREINIT_PRIME_SOURCE_BYTES + len(source) > MAX_PRIME_SOURCE_BYTES
        ):
            _PREINIT_PRIME_SKIPPED["source_limit"] += 1
            continue
        if len(_CACHE) >= MAX_ENTRIES:
            _PREINIT_PRIME_SKIPPED["entry_limit"] += 1
            continue
        if _PREINIT_PRIME_CALLS >= MAX_PRIME_ATTEMPTS:
            _PREINIT_PRIME_SKIPPED["attempt_limit"] += 1
            continue
        _PREINIT_PRIME_CALLS += 1
        _PREINIT_PRIME_SOURCE_BYTES += len(source)
        try:
            loader.get_code(fullname)
        except Exception:
            # A lazy source that cannot be compiled here remains on the original
            # runtime compile path and keeps its original SyntaxError timing.
            _PREINIT_PRIME_SKIPPED["compile_error_fallback"] += 1
        else:
            _PREINIT_PRIME_COMPLETED += 1


def _report_value() -> dict:
    entries = [_CACHE[key]["record"] for key in sorted(_CACHE)]
    digest = hashlib.sha256()
    for entry in entries:
        digest.update(bytes.fromhex(entry["cache_sha256"]))
    return {
        "format": FORMAT,
        "generation_phase": "componentize-py Wasm CPython preinit",
        "generation_source": (
            "captured_loader.Finder.find_spec(...).loader.get_code(fullname) "
            "for closed .py paths; Loader.get_code compiles exact captured bytes "
            "with mode=exec, flags=0, dont_inherit=True, optimize=-1; no bodies execute"
        ),
        "sealed_before_snapshot": _SEALED,
        "interpreter": _INTERPRETER,
        "preinit_compile_calls": _PREINIT_COMPILE_CALLS,
        "preinit_cached_calls": _PREINIT_CACHED_CALLS,
        "preinit_prime": {
            "attempts": _PREINIT_PRIME_CALLS,
            "completed": _PREINIT_PRIME_COMPLETED,
            "source_bytes": _PREINIT_PRIME_SOURCE_BYTES,
            "max_attempts": MAX_PRIME_ATTEMPTS,
            "max_source_bytes": MAX_PRIME_SOURCE_BYTES,
            "skipped_counts": dict(_PREINIT_PRIME_SKIPPED),
            "module_bodies_executed": False,
        },
        "cache_entry_count": len(entries),
        "cache_payload_sha256": digest.hexdigest(),
        "uncached_counts": dict(_UNCACHED),
        "entries": entries,
        "accounting": {
            "source_tree_accounted_bytes": _SOURCE_TREE_ACCOUNTED_BYTES,
            "cache_bytes": sum(row["cache_bytes"] for row in entries),
            "metadata_record_bytes": _RECORD_BYTES,
            "retained_code_graph_estimate_bytes": _CACHE_GRAPH_BYTES,
            "retained_accounted_bytes": _cache_accounted_bytes(),
            "report_text_bytes": 0,
            "peak_temporary_bytes": _PEAK_TEMPORARY_BYTES,
            "peak_code_graph_bytes": _PEAK_CODE_GRAPH_BYTES,
            "peak_marshal_buffer_bytes": _PEAK_MARSHAL_BYTES,
            "peak_combined_store_bytes": _PEAK_COMBINED_STORE_BYTES,
            "max_cache_accounted_bytes": MAX_CACHE_ACCOUNTED_BYTES,
            "max_temporary_bytes": MAX_TEMPORARY_BYTES,
            "capture_limit_bytes": CAPTURE_LIMIT_BYTES,
            "store_limit_bytes": STORE_LIMIT_BYTES,
        },
        "runtime_cache_use_observed": False,
        "audit_event_difference": {
            "compile": "preinit generation rather than runtime for cache entries",
            "marshal_loads": "runtime cache hits add marshal.loads audit events",
            "identical_to_original": False,
        },
        "diagnostic_only": True,
        "original_acceptance_claimed": False,
        "production_enabled": False,
    }


def seal() -> None:
    """Freeze the cache immediately before the app preinit snapshot boundary."""
    global _OPEN, _SEALED, _REPORT_TEXT, _PREINIT_SEEN, _PEAK_TEMPORARY_BYTES
    global _PEAK_COMBINED_STORE_BYTES
    if not _CONFIGURED or not _OPEN or _SEALED:
        raise RuntimeError("preinit code cache cannot be sealed in its current state")
    _OPEN = False
    _SEALED = True
    _PREINIT_SEEN.clear()
    _PREINIT_SEEN = None
    while True:
        report = _report_value()
        for _ in range(8):
            text = json.dumps(
                report, ensure_ascii=True, sort_keys=True, separators=(",", ":")
            )
            text_bytes = len(text.encode("ascii"))
            retained = _cache_accounted_bytes(text)
            previous = (
                report["accounting"]["report_text_bytes"],
                report["accounting"]["retained_accounted_bytes"],
            )
            report["accounting"]["report_text_bytes"] = text_bytes
            report["accounting"]["retained_accounted_bytes"] = retained
            if previous == (text_bytes, retained):
                break
        text = json.dumps(
            report, ensure_ascii=True, sort_keys=True, separators=(",", ":")
        )
        text_bytes = len(text.encode("ascii"))
        retained = _cache_accounted_bytes(text)
        peak_temporary = retained + _owned_size(report) + (text_bytes * 2)
        peak_combined = _SOURCE_TREE_ACCOUNTED_BYTES + peak_temporary
        if peak_combined > _PEAK_COMBINED_STORE_BYTES:
            _PEAK_COMBINED_STORE_BYTES = peak_combined
            continue
        if peak_temporary > _PEAK_TEMPORARY_BYTES:
            _PEAK_TEMPORARY_BYTES = peak_temporary
            continue
        if (
            text_bytes <= MAX_METADATA_BYTES
            and retained <= MAX_CACHE_ACCOUNTED_BYTES
            and _PEAK_TEMPORARY_BYTES <= MAX_TEMPORARY_BYTES
            and _SOURCE_TREE_ACCOUNTED_BYTES + retained <= CAPTURE_LIMIT_BYTES
            and _SOURCE_TREE_ACCOUNTED_BYTES + peak_temporary <= STORE_LIMIT_BYTES
        ):
            _REPORT_TEXT = text
            return
        if not _CACHE:
            report = {
                "format": FORMAT,
                "generation_phase": "componentize-py Wasm CPython preinit",
                "generation_source": (
                    "captured_loader.Finder.find_spec(...).loader.get_code(fullname) "
                    "for closed .py paths; Loader.get_code compiles exact captured "
                    "bytes with mode=exec, flags=0, dont_inherit=True, optimize=-1; "
                    "no bodies execute"
                ),
                "sealed_before_snapshot": True,
                "interpreter": _INTERPRETER,
                "preinit_compile_calls": _PREINIT_COMPILE_CALLS,
                "preinit_cached_calls": _PREINIT_CACHED_CALLS,
                "preinit_prime": {
                    "attempts": _PREINIT_PRIME_CALLS,
                    "completed": _PREINIT_PRIME_COMPLETED,
                    "source_bytes": _PREINIT_PRIME_SOURCE_BYTES,
                    "max_attempts": MAX_PRIME_ATTEMPTS,
                    "max_source_bytes": MAX_PRIME_SOURCE_BYTES,
                    "skipped_counts": dict(_PREINIT_PRIME_SKIPPED),
                    "module_bodies_executed": False,
                },
                "cache_entry_count": 0,
                "cache_payload_sha256": hashlib.sha256(b"").hexdigest(),
                "uncached_counts": dict(_UNCACHED),
                "entries": [],
                "accounting": {
                    "source_tree_accounted_bytes": _SOURCE_TREE_ACCOUNTED_BYTES,
                    "cache_bytes": 0,
                    "metadata_record_bytes": 0,
                    "retained_code_graph_estimate_bytes": 0,
                    "retained_accounted_bytes": 0,
                    "peak_temporary_bytes": _PEAK_TEMPORARY_BYTES,
                    "peak_code_graph_bytes": _PEAK_CODE_GRAPH_BYTES,
                    "peak_marshal_buffer_bytes": _PEAK_MARSHAL_BYTES,
                    "peak_combined_store_bytes": _PEAK_COMBINED_STORE_BYTES,
                    "max_cache_accounted_bytes": MAX_CACHE_ACCOUNTED_BYTES,
                    "max_temporary_bytes": MAX_TEMPORARY_BYTES,
                    "capture_limit_bytes": CAPTURE_LIMIT_BYTES,
                    "store_limit_bytes": STORE_LIMIT_BYTES,
                    "report_text_bytes": 0,
                },
                "runtime_cache_use_observed": False,
                "audit_event_difference": {
                    "compile": "preinit generation rather than runtime for cache entries",
                    "marshal_loads": "runtime cache hits add marshal.loads audit events",
                    "identical_to_original": False,
                },
                "diagnostic_only": True,
                "original_acceptance_claimed": False,
                "production_enabled": False,
            }
            for _ in range(8):
                text = json.dumps(
                    report,
                    ensure_ascii=True,
                    sort_keys=True,
                    separators=(",", ":"),
                )
                text_bytes = len(text.encode("ascii"))
                retained = _cache_accounted_bytes(text)
                previous = (
                    report["accounting"]["report_text_bytes"],
                    report["accounting"]["retained_accounted_bytes"],
                )
                report["accounting"]["report_text_bytes"] = text_bytes
                report["accounting"]["retained_accounted_bytes"] = retained
                peak_temporary = retained + _owned_size(report) + text_bytes * 2
                peak_combined = _SOURCE_TREE_ACCOUNTED_BYTES + peak_temporary
                if peak_temporary > _PEAK_TEMPORARY_BYTES:
                    _PEAK_TEMPORARY_BYTES = peak_temporary
                    report["accounting"]["peak_temporary_bytes"] = peak_temporary
                    continue
                if peak_combined > _PEAK_COMBINED_STORE_BYTES:
                    _PEAK_COMBINED_STORE_BYTES = peak_combined
                    report["accounting"]["peak_combined_store_bytes"] = peak_combined
                    continue
                if previous == (text_bytes, retained):
                    break
            _REPORT_TEXT = json.dumps(
                report, ensure_ascii=True, sort_keys=True, separators=(",", ":")
            )
            return
        _drop_last_entry()


def _drop_last_entry() -> None:
    global _CACHE_GRAPH_BYTES, _RECORD_BYTES
    key = next(reversed(_CACHE))
    cached = _CACHE.pop(key)
    record = cached["record"]
    _CACHE_GRAPH_BYTES -= record["code_graph_bytes"]
    _RECORD_BYTES -= len(
        json.dumps(record, ensure_ascii=True, sort_keys=True, separators=(",", ":"))
    )
    _UNCACHED["memory_limit"] += 1


def report() -> str:
    """Return sealed preinit metadata as bounded DATA to the existing clock export."""
    if not _SEALED or _REPORT_TEXT is None:
        raise RuntimeError("preinit code cache report is not sealed")
    return _REPORT_TEXT


def runtime_stats() -> dict:
    """Report this Store's actual runtime behavior only when the app returns."""
    return {
        "format": FORMAT,
        "runtime_cache_use_observed": True,
        "cache_hits": _RUNTIME_HITS,
        "cache_misses": _RUNTIME_MISSES,
        "runtime_compiles": _RUNTIME_COMPILES,
        "marshal_loads": _MARSHAL_LOADS,
        "diagnostic_only": True,
        "production_enabled": False,
    }
